// Offline cache for the Yi guide. Generated by build.py; the version changes whenever the page does.
const VERSION='a948ad82f9';
const SHELL='shell-'+VERSION, CARDS='cards', FONTS='fonts';
const SHELL_FILES=['./','manifest.webmanifest','icons/icon-192.png','icons/icon-512.png'];
// Card filenames come from Riot's image hash, so a file never changes: cache them forever.
