const abs=f=>new URL(f,self.registration.scope).href;

self.addEventListener('install',e=>{
  e.waitUntil(caches.open(SHELL).then(c=>c.addAll(SHELL_FILES)).then(()=>self.skipWaiting()));
});

self.addEventListener('activate',e=>{
  e.waitUntil((async()=>{
    for(const k of await caches.keys()) if(k.startsWith('shell-')&&k!==SHELL) await caches.delete(k);
    const c=await caches.open(CARDS), keep=new Set(CARD_FILES.map(abs));
    for(const r of await c.keys()) if(!keep.has(r.url)) await c.delete(r);
    await self.clients.claim();
  })());
});

// The page asks for this on every load (unless Data Saver is on); only missing cards are fetched.
self.addEventListener('message',e=>{if(e.data==='precache-cards') e.waitUntil(precacheCards());});
async function precacheCards(){
  const c=await caches.open(CARDS), have=new Set((await c.keys()).map(r=>r.url));
  const todo=CARD_FILES.map(abs).filter(u=>!have.has(u));
  for(let i=0;i<todo.length;i+=6)
    await Promise.all(todo.slice(i,i+6).map(u=>fetch(u).then(r=>r.ok&&c.put(u,r)).catch(()=>{})));
}

self.addEventListener('fetch',e=>{
  const r=e.request; if(r.method!=='GET') return;
  const u=new URL(r.url);
  if(u.origin===location.origin){
    if(r.mode==='navigate') e.respondWith(staleWhileRevalidate(SHELL,new Request(self.registration.scope),e));
    else if(u.pathname.includes('/cards/')) e.respondWith(cacheFirst(CARDS,r));
    else e.respondWith(staleWhileRevalidate(SHELL,r,e));
  } else if(u.hostname==='fonts.googleapis.com'||u.hostname==='fonts.gstatic.com'){
    e.respondWith(staleWhileRevalidate(FONTS,r,e));
  }
});

async function cacheFirst(name,req){
  const c=await caches.open(name), hit=await c.match(req);
  if(hit) return hit;
  const res=await fetch(req);
  if(res.ok) c.put(req,res.clone());
  return res;
}

// Serve the saved copy at once and refresh it in the background; the update shows on the next visit.
async function staleWhileRevalidate(name,req,e){
  const c=await caches.open(name), hit=await c.match(req);
  const net=fetch(req).then(res=>{if(res.ok||res.type==='opaque') c.put(req,res.clone()); return res;});
  if(hit){e.waitUntil(net.catch(()=>{})); return hit;}
  return net;
}
